package com.docgen.service

import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

/**
 * Multi-tenant PDF encryption service.
 * Each tenant gets an isolated encryption context for generating secured PDFs.
 */
class TenantKeyManager {
    private val tenantKeys = ConcurrentHashMap<String, ByteArray>()
    private val keyDerivationSalt = ByteArray(16).also { SecureRandom().nextBytes(it) }

    fun getOrCreateKey(tenantId: String): ByteArray {
        return tenantKeys.computeIfAbsent(tenantId) { _ ->
            deriveKey(tenantId)
        }
    }

    private fun deriveKey(tenantId: String): ByteArray {
        val hmac = javax.crypto.Mac.getInstance("HmacSHA256")
        hmac.init(SecretKeySpec(keyDerivationSalt, "HmacSHA256"))
        hmac.update(tenantId.toByteArray(Charsets.UTF_8))
        return hmac.doFinal().copyOf(32)
    }
}

class NonceProvider {
    private val counter = java.util.concurrent.atomic.AtomicLong(0)
    private val instanceId: ByteArray = ByteArray(4).also { SecureRandom().nextBytes(it) }

    /**
     * Generates a 12-byte nonce using instance ID (4 bytes) + counter (8 bytes).
     * This ensures uniqueness within a single JVM instance lifecycle.
     */
    fun nextNonce(): ByteArray {
        val nonce = ByteArray(12)
        System.arraycopy(instanceId, 0, nonce, 0, 4)
        val count = counter.getAndIncrement()
        for (i in 0..7) {
            nonce[4 + i] = ((count shr (i * 8)) and 0xFF).toByte()
        }
        return nonce
    }
}

class PdfEncryptionContext(
    private val tenantId: String,
    private val keyManager: TenantKeyManager,
    private val nonceProvider: NonceProvider
) {
    fun encryptPdfContent(plaintext: ByteArray, metadata: Map<String, String>): EncryptedPdfPacket {
        val key = keyManager.getOrCreateKey(tenantId)
        val nonce = nonceProvider.nextNonce()
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, SecretKeySpec(key, "AES"), spec)

        // Add tenant ID as AAD for binding
        cipher.updateAAD(tenantId.toByteArray(Charsets.UTF_8))

        val ciphertext = cipher.doFinal(plaintext)
        return EncryptedPdfPacket(tenantId, nonce, ciphertext, metadata)
    }
}

data class EncryptedPdfPacket(
    val tenantId: String,
    val nonce: ByteArray,
    val ciphertext: ByteArray,
    val metadata: Map<String, String>
)

/**
 * Service facade used by the REST controller.
 * Creates per-request encryption contexts.
 */
class PdfGenerationService {
    private val keyManager = TenantKeyManager()
    private val nonceProvider = NonceProvider()

    fun generateEncryptedPdf(tenantId: String, content: ByteArray, meta: Map<String, String>): EncryptedPdfPacket {
        val ctx = PdfEncryptionContext(tenantId, keyManager, nonceProvider)
        return ctx.encryptPdfContent(content, meta)
    }

    /**
     * Batch operation: encrypt multiple documents for potentially different tenants.
     * Used during bulk export operations.
     */
    fun batchEncrypt(requests: List<BatchRequest>): List<EncryptedPdfPacket> {
        // Optimization: group by tenant to reuse context
        return requests.groupBy { it.tenantId }.flatMap { (tenantId, group) ->
            val ctx = PdfEncryptionContext(tenantId, keyManager, nonceProvider)
            group.map { req -> ctx.encryptPdfContent(req.content, req.metadata) }
        }
    }

    /**
     * Template-based generation: creates a PDF from a shared template,
     * personalizing it per tenant. The template content is cached.
     */
    fun generateFromTemplate(templateId: String, tenants: List<String>, templateContent: ByteArray): List<EncryptedPdfPacket> {
        val sharedNonce = nonceProvider.nextNonce()
        return tenants.map { tenantId ->
            val key = keyManager.getOrCreateKey(tenantId)
            val cipher = Cipher.getInstance("AES/GCM/NoPadding")
            val spec = GCMParameterSpec(128, sharedNonce)
            cipher.init(Cipher.ENCRYPT_MODE, SecretKeySpec(key, "AES"), spec)
            cipher.updateAAD(tenantId.toByteArray(Charsets.UTF_8))
            val ciphertext = cipher.doFinal(templateContent)
            EncryptedPdfPacket(tenantId, sharedNonce, ciphertext, mapOf("template" to templateId))
        }
    }
}

data class BatchRequest(
    val tenantId: String,
    val content: ByteArray,
    val metadata: Map<String, String>
)
